-- tests/buttons/effects.lua: what every button and setting must do, one table per page group (the groups are in tests/buttons/lib.lua).
-- A row is { id, action = "click", expect = "changed" } (after the real click something visible differs: screen, shown frames, text,
-- a check state, a toast or a popup), { id, action = "click", expect = "same", why } (the click is taken by the control and nothing
-- visible changes, and why) or { id, skip = "<why no click is made: talks to other players, a secure macro, the game's own window,
-- or a sheet drawn over it in that state>" }, or any row in E.ALLOWED_TODO may carry todo = "<why>" (any other todo
-- fails the coverage test). "on" names the screen the click was made on. Skip rows are never clicked (the suite asserts it): a protected (secure) button is skipped by what it IS, never by its label.
-- A click that makes the fake game record something sent (addon message, whisper, chat post, invite, macro, trade) must say so in its row:
-- sends = "<what, why fine offline>"; a click that sends with no sends field fails the fourth test, and so does a sends field with no send.
-- A row with expect = "same" asserts the snapshot (texts, shown frames, check states, edit texts) is unchanged after the click. An id is
-- "<label> <Type> @<file that made it>": a control the suite sees with no row, or a row whose control is gone, fails the coverage test.
-- Settings are controls of the Settings screens: each setting row is a row of its page group.
local E = { groups = {}, ALLOWED_TODO = {} }
function E.rowsFor(group) local out = {} for _, r in ipairs(E.groups[group] or {}) do out[r.id] = r end return out end
local G = E.groups
